Local Ltac nodup_fin :=
  repeat (apply NoDup_cons; [cbn [In app]; let HH := fresh "HH" in intros HH;
                             repeat match goal with H : _ \/ _ |- _ => destruct H as [H|H] end;
                             first [ exact HH
                                   | match goal with N : _ <> _ |- _ => first [ exact (N HH) | exact (N (eq_sym HH)) ] end ] |]);
  apply NoDup_nil.

